export default "alled();\\n      expect(mockRefreshAllModelInputs).toHaveBeenCalledWith({ silent: true });\\n    } finally {\\n      dateNowSpy.mockRestore();\\n    }\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/DisconnectWarning.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"51f635842827fdd55d0bae445a7e1e6efd9891c380092964c7001613c11f37f9\",\"content\":\"import { useTranslation } from \\\"react-i18next\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport {\\n  Dialog,\\n  DialogContent,\\n  DialogDescription,\\n  DialogFooter,\\n  DialogHeader,\\n  DialogTitle,\\n} from \\\"@/components/ui/dialog\\\";\\n\\ninterface DisconnectWarningProps {\\n  show: boolean;\\n  message: string;\\n  onCancel: () => void;\\n  onConfirm: () => void;\\n  isLoading: boolean;\\n  className?: string;\\n}\\n\\nconst DisconnectWarning = ({\\n  show,\\n  message,\\n  onCancel,\\n  onConfirm,\\n  isLoading,\\n  className,\\n}: DisconnectWarningProps) => {\\n  const { t } = useTranslation();\\n\\n  return (\\n    <Dialog\\n      open={show}\\n      onOpenChange={(open) => {\\n        if (!open) {\\n          onCancel();\\n        }\\n      }}\\n    >\\n      <DialogContent\\n        hideCloseButton\\n        className={className}\\n        onOpenAutoFocus={(e) => {\\n          // Move focus to Cancel (least destructive action) on open.\\n          e.preventDefault();\\n          const cancelButton = (e.currentTarget as HTMLElement).querySelector(\\n            '[data-testid=\\\"disconnect-warning-cancel\\\"]',\\n          ) as HTMLElement | null;\\n          cancelButton?.focus();\\n        }}\\n      >\\n        <DialogHeader>\\n          <DialogTitle className=\\\"text-destructive flex items-center gap-1 text-md\\\">\\n            <ForwardedIconComponent\\n              name=\\\"Circle\\\"\\n              className=\\\"text-destructive w-3 h-3 fill-destructive mr-2 animate-pulse\\\"\\n              ariaHidden\\n            />\\n            {t(\\\"modelProviders.warning\\\")}\\n          </DialogTitle>\\n        </DialogHeader>\\n\\n        <DialogDescription className=\\\"text-sm text-foreground\\\">\\n          {message}\\n        </DialogDescription>\\n\\n        <DialogFooter>\\n          <Button\\n            size=\\\"sm\\\"\\n            variant=\\\"ghost\\\"\\n            onClick={onCancel}\\n            data-testid=\\\"disconnect-warning-cancel\\\"\\n          >\\n            {t(\\\"modelProviders.cancelButton\\\")}\\n          </Button>\\n          <Button\\n            size=\\\"sm\\\"\\n            variant=\\\"destructive\\\"\\n            onClick={onConfirm}\\n            loading={isLoading}\\n            data-testid=\\\"disconnect-warning-confirm\\\"\\n          >\\n            {t(\\\"modelProviders.confirmButton\\\")}\\n          </Button>\\n        </DialogFooter>\\n      </DialogContent>\\n    </Dialog>\\n  );\\n};\\n\\nexport default DisconnectWarning;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/ModelProvidersContent.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b04adb92e2ccc8fd50d8d95f852a51c441212a82577be142a83af06fa17acfa\",\"content\":\"import { useEffect, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport { Input } from \\\"@/components/ui/input\\\";\\nimport type { ProviderScopeParams } from \\\"@/controllers/API/helpers/provider-scope\\\";\\nimport CustomModelProvidersEmptyState from \\\"@/customization/components/custom-model-providers-empty-state\\\";\\nimport ProviderList from \\\"@/modals/modelProviderModal/components/ProviderList\\\";\\nimport { Provider } from \\\"@/modals/modelProviderModal/components/types\\\";\\nimport type { ModelTypeFilter } from \\\"@/types/models\\\";\\nimport { cn } from \\\"@/utils/utils\\\";\\nimport { useProviderConfiguration } from \\\"../hooks/useProviderConfiguration\\\";\\nimport ModelSelection, { hasProviderOwnedEmptyState } from \\\"./ModelSelection\\\";\\nimport ProviderConfigurationForm from \\\"./ProviderConfigurationForm\\\";\\n\\ninterface ModelProvidersContentProps extends ProviderScopeParams {\\n  modelType: ModelTypeFilter;\\n  onFlushRef?: React.MutableRefObject<(() => Promise<void>) | null>;\\n  onHasChangesRef?: React.MutableRefObject<(() => boolean) | null>;\\n}\\n\\nconst ModelProvidersContent = ({\\n  modelType,\\n  onFlushRef,\\n  onHasChangesRef,\\n  flowId,\\n  projectId,\\n}: ModelProvidersContentProps) => {\\n  const { t } = useTranslation();\\n  const [selectedProvider, setSelectedProvider] = useState<Provider | null>(\\n    null,\\n  );\\n  const [providerQuery, setProviderQuery] = useState<string>(\\\"\\\");\\n\\n  // Use the custom hook for provider configuration logic\\n  const {\\n    variableValues,\\n    validationFailed,\\n    isSaving,\\n    isPending,\\n    isDeleting,\\n    isFetchingAfterSave,\\n    isFetchingAfterDisconnect,\\n    handleVariableChange,\\n    handleSaveAllVariables,\\n    handleActivateProvider,\\n    handleDisconnect,\\n    isVariableConfigured,\\n    getConfiguredValue,\\n    validationState,\\n    validationError,\\n    canSave,\\n    providerVariables,\\n    syncedSelectedProvider,\\n    handleModelToggle,\\n    flushPendingChanges,\\n    hasUserMadeChanges,\\n    requiresConfiguration,\\n  } = useProviderConfiguration({\\n    selectedProvider,\\n    flowId,\\n    projectId,\\n  });\\n\\n  // Expose flushPendingChanges and hasUserMadeChanges to the parent\\n  // (ModelProviderModal) via refs so it can decide whether to refresh model\\n  // inputs on close.\\n  useEffect(() => {\\n    if (onFlushRef) {\\n      onFlushRef.current = flushPendingChanges;\\n    }\\n    if (onHasChangesRef) {\\n      onHasChangesRef.current = hasUserMadeChanges;\\n    }\\n    return () => {\\n      if (onFlushRef) {\\n        onFlushRef.current = null;\\n      }\\n      if (onHasChangesRef) {\\n        onHasChangesRef.current = null;\\n      }\\n    };\\n  }, [onFlushRef, onHasChangesRef, flushPendingChanges, hasUserMadeChanges]);\\n\\n  const handleProviderSelect = (provider: Provider) => {\\n    setSelectedProvider((prev) =>\\n      prev?.provider === provider.provider ? null : provider,\\n    );\\n  };\\n\\n  const typedModelCount = (syncedSelectedProvider?.models ?? []).filter(\\n    (model) => modelType === \\\"all\\\" || model.metadata?.model_type === modelType,\\n  ).length;\\n  // Providers whose catalog is discovered from their endpoint have no models\\n  // to show until credentials are configured; ModelSelection renders a\\n  // configure-credentials hint for them instead of the generic empty state.\\n  const awaitingLiveDiscovery =\\n    !!syncedSelectedProvider?.live_discovery &&\\n    !syncedSelectedProvider?.is_configured;\\n  const showNoAvailableModels =\\n    !!syncedSelectedProvider &&\\n    typedModelCount === 0 &&\\n    !awaitingLiveDiscovery &&\\n    !hasProviderOwnedEmptyState(syncedSelectedProvider.provider);\\n\\n  return (\\n    <div className=\\\"flex flex-row w-full h-full overflow-hidden\\\">\\n      <div\\n        className={cn(\\n          \\\"flex p-2 flex-col flex-shrink-0 transition-all duration-300 ease-in-out\\\",\\n          syncedSelectedProvider ? \\\"w-1/3 border-r\\\" : \\\"w-full\\\",\\n        )}\\n      >\\n        <Input\\n          icon=\\\"Search\\\"\\n          value={providerQuery}\\n          onChange={(event) => setProviderQuery(event.target.value)}\\n          placeholder={t(\\\"modelProviders.searchProviders\\\", {\\n            defaultValue: \\\"Search providers\u2026\\\",\\n          })}\\n          aria-label={t(\\\"modelProviders.searchProviders\\\", {\\n            defaultValue: \\\"Search providers\u2026\\\",\\n          })}\\n          data-testid=\\\"provider-search-input\\\"\\n          className=\\\"mb-2\\\"\\n        />\\n        <ProviderList\\n          modelType={modelType}\\n          onProviderSelect={handleProviderSelect}\\n          selectedProviderName={syncedSelectedProvider?.provider ?? null}\\n          query={providerQuery}\\n          flowId={flowId}\\n          projectId={projectId}\\n        />\\n      </div>\\n\\n      <div\\n        className={cn(\\n          \\\"flex min-h-0 flex-col gap-1 transition-all duration-300 ease-in-out\\\",\\n          syncedSelectedProvider\\n            ? \\\"w-2/3 opacity-100 translate-x-0\\\"\\n            : \\\"w-0 opacity-0 translate-x-full\\\",\\n        )}\\n      >\\n        <ProviderConfigurationForm\\n          key={syncedSelectedProvider?.provider}\\n          selectedProvider={syncedSelectedProvider}\\n          providerVariables={providerVariables}\\n          variableValues={variableValues}\\n          isVariableConfigured={isVariableConfigured}\\n          getConfiguredValue={getConfiguredValue}\\n          onVariableChange={handleVariableChange}\\n          onSave={handleSaveAllVariables}\\n          onActivate={handleActivateProvider}\\n          onDisconnect={handleDisconnect}\\n          isSaving={isSaving}\\n          isPending={isPending}\\n          isDeleting={isDeleting}\\n          isFetchingModels={isFetchingAfterSave}\\n          isFetchingAfterDisconnect={isFetchingAfterDisconnect}\\n          validationFailed={validationFailed}\\n          validationState={validationState}\\n          validationError={validationError}\\n          canSave={canSave}\\n          requiresConfiguration={requiresConfiguration}\\n        />\\n\\n        {/* hidden while collapsed: the padded scroller inside has intrinsic\\n            width, so it would stick out of the w-0 column and register as\\n            clipped content at a 320px viewport (WCAG 1.4.10). */}\\n        <div\\n          className={cn(\\n            \\\"relative flex min-h-0 flex-1 flex-col\\\",\\n            !syncedSelectedProvider && \\\"hidden\\\",\\n          )}\\n        >\\n          <div className=\\\"flex h-full flex-col gap-3 overflow-y-auto px-4 pt-4 pb-6 transition-all duration-300 ease-in-out\\\">\\n            <CustomModelProvidersEmptyState\\n              kind=\\\"models\\\"\\n              show={showNoAvailableModels}\\n            >\\n              <ModelSelection\\n                modelType={modelType}\\n                availableModels={syncedSelectedProvider?.models || []}\\n                onModelToggle={handleModelToggle}\\n                providerName={syncedSelectedProvider?.provider}\\n                isEnabledModel={\\n                  !!(\\n                    syncedSelectedProvider?.is_enabled ||\\n                    syncedSelectedProvider?.is_configured\\n                  )\\n                }\\n                liveDiscovery={!!syncedSelectedProvider?.live_discovery}\\n                isConfigured={!!syncedSelectedProvider?.is_configured}\\n                flowId={flowId}\\n                projectId={projectId}\\n              />\\n            </CustomModelProvidersEmptyState>\\n          </div>\\n          <div className=\\\"pointer-events-none absolute inset-x-0 top-0 h-6 bg-gradient-to-b from-background via-background/70 to-transparent\\\" />\\n          <div className=\\\"pointer-events-none absolute inset-x-0 bottom-0 h-8 bg-gradient-to-t from-background via-background/70 to-transparent\\\" />\\n        </div>\\n      </div>\\n    </div>\\n  );\\n};\\n\\nexport default ModelProvidersContent;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/ModelSelection.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8f7e62e918545992bec2a13212c20605776399bafb5190b4e12f736fda31fd3b\",\"content\":\"import { useEffect, useMemo, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport { Badge } from \\\"@/components/ui/badge\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport { Input } from \\\"@/components/ui/input\\\";\\nimport { Switch } from \\\"@/components/ui/switch\\\";\\nimport type { ProviderScopeParams } from \\\"@/controllers/API/helpers/provider-scope\\\";\\nimport { useGetEnabledModels } from \\\"@/controllers/API/queries/models/use-get-enabled-models\\\";\\n\\nimport { Model } from \\\"@/modals/modelProviderModal/components/types\\\";\\nimport type { ModelType, ModelTypeFilter } from \\\"@/types/models\\\";\\nimport { cn } from \\\"@/utils/utils\\\";\\n\\n/** Providers where the callable model id is a user-chosen deployment name. */\\nconst CUSTOM_DEPLOYMENT_PROVIDERS = new Set([\\\"Azure AI Foundry\\\"]);\\n\\n/** Providers that render their own useful UI when no catalog models exist. */\\nexport const hasProviderOwnedEmptyState = (providerName?: string): boolean =>\\n  !!providerName &&\\n  (CUSTOM_DEPLOYMENT_PROVIDERS.has(providerName) ||\\n    providerName.toLowerCase() === \\\"ollama\\\");\\n\\nexport interface ModelProviderSelectionProps extends ProviderScopeParams {\\n  availableModels: Model[];\\n  onModelToggle: (\\n    modelName: string,\\n    enabled: boolean,\\n    modelType: ModelType,\\n  ) => void;\\n  modelType: ModelTypeFilter;\\n  providerName?: string;\\n  isEnabledModel?: boolean;\\n  /** True when the provider's model list is discovered from its endpoint\\n   *  after credentials are configured (backend ``live_discovery`` flag). */\\n  liveDiscovery?: boolean;\\n  /** True when the provider's credentials are already configured. */\\n  isConfigured?: boolean;\\n}\\n\\ninterface ModelRowProps {\\n  model: Model;\\n  modelType: ModelType;\\n  enabled: boolean;\\n  onToggle: (modelName: string, enabled: boolean, modelType: ModelType) => void;\\n  testIdPrefix: string;\\n  isEnabledModel?: boolean;\\n  /** When true (modelType === \\\"all\\\" view), show the \\\"embedding\\\" tag on\\n   *  embedding models. In dedicated embedding sections the tag is redundant. */\\n  showEmbeddingTag?: boolean;\\n}\\n\\n/** Tag descriptor consumed by ModelRow. */\\ninterface CapabilityTag {\\n  /** Stable identifier (used in test ids and as React key). */\\n  id: string;\\n  /** Short label shown inside the Badge. */\\n  label: string;\\n}\\n\\n/** Stable left-to-right ordering for the capability badges. */\\nconst TAG_ORDER: Array<CapabilityTag[\\\"id\\\"]> = [\\n  \\\"embedding\\\",\\n  \\\"tool\\\",\\n  \\\"reasoning\\\",\\n  \\\"vision\\\",\\n  \\\"search\\\",\\n  \\\"preview\\\",\\n];\\n\\nconst buildCapabilityTags = (\\n  model: Model,\\n  showEmbeddingTag: boolean,\\n  t: (key: string, options?: { defaultValue: string }) => string,\\n): CapabilityTag[] => {\\n  const metadata = (model.metadata ?? {}) as Record<string, unknown>;\\n  const isEmbedding = metadata.model_type === \\\"embeddings\\\";\\n  const tags: Record<string, CapabilityTag> = {};\\n\\n  if (showEmbeddingTag && isEmbedding) {\\n    tags.embedding = {\\n      id: \\\"embedding\\\",\\n      label: t(\\\"modelProviders.tag.embedding\\\", { defaultValue: \\\"embedding\\\" }),\\n    };\\n  }\\n  if (metadata.tool_calling === true) {\\n    tags.tool = {\\n      id: \\\"tool\\\",\\n      label: t(\\\"modelProviders.tag.tool\\\", { defaultValue: \\\"tool\\\" }),\\n    };\\n  }\\n  if (metadata.reasoning === true) {\\n    tags.reasoning = {\\n      id: \\\"reasoning\\\",\\n      label: t(\\\"modelProviders.tag.reasoning\\\", { defaultValue: \\\"reasoning\\\" }),\\n    };\\n  }\\n  if (metadata.vision === true) {\\n    tags.vision = {\\n      id: \\\"vision\\\",\\n      label: t(\\\"modelProviders.tag.vision\\\", { defaultValue: \\\"vision\\\" }),\\n    };\\n  }\\n  if (metadata.search === true) {\\n    tags.search = {\\n      id: \\\"search\\\",\\n      label: t(\\\"modelProviders.tag.search\\\", { defaultValue: \\\"search\\\" }),\\n    };\\n  }\\n  if (metadata.preview === true) {\\n    tags.preview = {\\n      id: \\\"preview\\\",\\n      label: t(\\\"modelProviders.tag.preview\\\", { defaultValue: \\\"preview\\\" }),\\n    };\\n  }\\n\\n  return TAG_ORDER.map((id) => tags[id]).filter((tag): tag is CapabilityTag =>\\n    Boolean(tag),\\n  );\\n};\\n\\n/** Single row displaying a model with its toggle switch */\\nconst ModelRow = ({\\n  onToggle,\\n  model,\\n  modelType,\\n  enabled,\\n  testIdPrefix,\\n  isEnabledModel,\\n  showEmbeddingTag,\\n}: ModelRowProps) => {\\n  const { t } = useTranslation();\\n  const tags = buildCapabilityTags(model, !!showEmbeddingTag, t);\\n\\n  return (\\n    <div className=\\\"flex flex-row items-center justify-between h-[24px]\\\">\\n      <div className=\\\"flex flex-row items-center gap-2\\\">\\n        <ForwardedIconComponent\\n          name={model.metadata?.icon || \\\"Bot\\\"}\\n          className={cn(\\\"w-5 h-5\\\", { grayscale: !isEnabledModel })}\\n        />\\n        <span\\n          className={cn(\\\"text-sm\\\", {\\n            \\\"text-muted-foreground\\\": !isEnabledModel,\\n          })}\\n        >\\n          {model.model_name}\\n        </span>\\n        {tags.map((tag) => (\\n          <Badge\\n            key={tag.id}\\n            variant=\\\"secondaryStatic\\\"\\n            size=\\\"tag\\\"\\n            data-testid={`${testIdPrefix}-tag-${tag.id}-${model.model_name}`}\\n          >\\n            {tag.label}\\n          </Badge>\\n        ))}\\n        {model.metadata?.deprecated ? (\\n          <Badge\\n            variant=\\\"secondaryStatic\\\"\\n            size=\\\"tag\\\"\\n            data-testid={`${testIdPrefix}-deprecated-${model.model_name}`}\\n          >\\n            {t(\\\"modelProvider.deprecated\\\")}\\n          </Badge>\\n        ) : null}\\n      </div>\\n      {isEnabledModel && (\\n        <Switch\\n          checked={enabled}\\n          disabled={\\n            model.metadata?.deprecated === true ||\\n            model.metadata?.not_supported === true\\n          }\\n          onCheckedChange={(checked) =>\\n            onToggle(model.model_name, checked, modelType)\\n          }\\n          data-testid={`${testIdPrefix}-toggle-${model.model_name}`}\\n          aria-label={\\n            enabled\\n              ? t(\\\"modelProvider.disableModel\\\", { modelName: model.model_name })\\n              : t(\\\"modelProvider.enableModel\\\", { modelName: model.model_name })\\n          }\\n          stopPropagation\\n        />\\n      )}\\n    </div>\\n  );\\n};\\n\\n/**\\n * Displays lists of LLM and embedding models with toggle switches.\\n * Allows users to enable/disable individual models for a provider.\\n */\\nconst ModelSelection = ({\\n  modelType = \\\"llm\\\",\\n  availableModels,\\n  onModelToggle,\\n  providerName,\\n  isEnabledModel,\\n  liveDiscovery,\\n  isConfigured,\\n  flowId,\\n  projectId,\\n}: ModelProviderSelectionProps) => {\\n  const { t } = useTranslation();\\n  const {\\n    data: enabledModelsData,\\n    isSuccess: isEnabledModelsSuccess,\\n    isFetching: isEnabledModelsFetching,\\n    isFetchedAfterMount: isEnabledModelsFetchedAfterMount,\\n    fetchStatus: enabledModelsFetchStatus,\\n    isError: isEnabledModelsError,\\n    refetch: refetchEnabledModels,\\n  } = useGetEnabledModels({ flowId, projectId, purpose: \\\"configure\\\" });\\n  const [modelQuery, setModelQuery] = useState<string>(\\\"\\\");\\n  const [showDeprecated, setShowDeprecated] = useState<boolean>(false);\\n  const canUseEnabledModels =\\n    !!enabledModelsData &&\\n    isEnabledModelsSuccess &&\\n    !isEnabledModelsFetching &&\\n    isEnabledModelsFetchedAfterMount &&\\n    enabledModelsFetchStatus === \\\"idle\\\";\\n\\n  // Reset both the search and the deprecated disclosure when the selected\\n  // provider changes so neither state leaks across providers\\n  // (OpenRouter \u2192 Anthropic, etc.).\\n  useEffect(() => {\\n    setModelQuery(\\\"\\\");\\n    setShowDeprecated(false);\\n  }, [providerName]);\\n\\n  const isModelEnabled = (\\n    modelName: string,\\n    selectedModelType: ModelType,\\n  ): boolean => {\\n    if (\\n      !canUseEnabledModels ||\\n      !providerName ||\\n      !enabledModelsData.enabled_models\\n    ) {\\n      return false;\\n    }\\n\\n    const typedProvider =\\n      enabledModelsData.enabled_models_by_type?.[providerName];\\n    if (typedProvider !== undefined) {\\n      return typedProvider[selectedModelType]?.[modelName] ?? false;\\n    }\\n\\n    return enabledModelsData.enabled_models[providerName]?.[modelName] ?? false;\\n  };\\n\\n  const supportsCustomDeployments =\\n    !!providerName && CUSTOM_DEPLOYMENT_PROVIDERS.has(providerName);\\n\\n  const visibleDeploymentTypes = useMemo<ModelType[]>(\\n    () => (modelType === \\\"all\\\" ? [\\\"llm\\\", \\\"embeddings\\\"] : [modelType]),\\n    [modelType],\\n  );\\n\\n  // Merge enabled free-text deployments; typed API wins, legacy customs default to llm.\\n  const modelsWithCustomDeployments = useMemo(() => {\\n    if (!canUseEnabledModels) {\\n      return [];\\n    }\\n    if (!supportsCustomDeployments || !providerName) {\\n      return availableModels;\\n    }\\n\\n    const flatEnabledForProvider =\\n      enabledModelsData?.enabled_models?.[providerName] ?? {};\\n    const typedEnabledForProvider =\\n      enabledModelsData?.enabled_models_by_type?.[providerName];\\n    const knownNames = new Set(\\n      availableModels.map((model) => model.model_name),\\n    );\\n    const knownTypedNames = new Set(\\n      availableModels.map(\\n        (model) =>\\n          `${model.metadata?.model_type ?? \\\"llm\\\"}\\\\0${model.model_name}`,\\n      ),\\n    );\\n    const customModels: Model[] = [];\\n\\n    if (typedEnabledForProvider !== undefined) {\\n      for (const deploymentType of visibleDeploymentTypes) {\\n        for (const [name, enabled] of Object.entries(\\n          typedEnabledForProvider[deploymentType] ?? {},\\n        )) {\\n          if (!enabled || knownTypedNames.has(`${deploymentType}\\\\0${name}`)) {\\n            continue;\\n          }\\n          customModels.push({\\n            model_name: name,\\n            metadata: {\\n              model_type: deploymentType,\\n              icon: \\\"Azure\\\",\\n            },\\n          });\\n        }\\n      }\\n    } else if (visibleDeploymentTypes.includes(\\\"llm\\\")) {\\n      for (const [name, enabled] of Object.entries(flatEnabledForProvider)) {\\n        if (!enabled || knownNames.has(name)) continue;\\n        customModels.push({\\n          model_name: name,\\n          metadata: {\\n            model_type: \\\"llm\\\",\\n            icon: \\\"Azure\\\",\\n          },\\n        });\\n      }\\n    }\\n    return customModels.length > 0\\n      ? [...availableModels, ...customModels]\\n      : availableModels;\\n  }, [\\n    availableModels,\\n    canUseEnabledModels,\\n    enabledModelsData?.enabled_models,\\n    enabledModelsData?.enabled_models_by_type,\\n    providerName,\\n    supportsCustomDeployments,\\n    visibleDeploymentTypes,\\n  ]);\\n\\n  const trimmedModelQuery = modelQuery.trim();\\n  const trimmedModelQueryLower = trimmedModelQuery.toLowerCase();\\n\\n  const matchesModelQuery = (model: Model): boolean =>\\n    trimmedModelQueryLower.length === 0 ||\\n    model.model_name.toLowerCase().includes(trimmedModelQueryLower);\\n\\n  const llmModels = useMemo(\\n    () =>\\n      modelsWithCustomDeployments.filter(\\n        (model) =>\\n          model.metadata?.model_type === \\\"llm\\\" && matchesModelQuery(model),\\n      ),\\n    [modelsWithCustomDeployments, trimmedModelQueryLower],\\n  );\\n  const embeddingModels = useMemo(\\n    () =>\\n      modelsWithCustomDeployments.filter(\\n        (model) =>\\n          model.metadata?.model_type === \\\"embeddings\\\" &&\\n          matchesModelQuery(model),\\n      ),\\n    [modelsWithCustomDeployments, trimmedModelQueryLower],\\n  );\\n\\n  const addableDeploymentTypes =\\n    canUseEnabledModels &&\\n    supportsCustomDeployments &&\\n    isEnabledModel &&\\n    trimmedModelQuery.length > 0\\n      ? visibleDeploymentTypes.filter(\\n          (deploymentType) =>\\n            !modelsWithCustomDeployments.some(\\n              (model) =>\\n                model.metadata?.model_type === deploymentType &&\\n                model.model_name.toLowerCase() === trimmedModelQueryLower,\\n            ),\\n        )\\n      : [];\\n  const canAddCustomDeployment = addableDeploymentTypes.length > 0;\\n\\n  const partitionDeprecated = (models: Model[]): [Model[], Model[]] => {\\n    const active: Model[] = [];\\n    const deprecated: Model[] = [];\\n    for (const model of models) {\\n      if (model.metadata?.deprecated) {\\n        deprecated.push(model);\\n      } else {\\n        active.push(model);\\n      }\\n    }\\n    return [active, deprecated];\\n  };\\n\\n  const renderModelRow = (model: Model, selectedModelType: ModelType) => (\\n    <ModelRow\\n      key={model.model_name}\\n      model={model}\\n      modelType={selectedModelType}\\n      enabled={isModelEnabled(model.model_name, selectedModelType)}\\n      onToggle={onModelToggle}\\n      testIdPrefix={selectedModelType}\\n      isEnabledModel={isEnabledModel}\\n      showEmbeddingTag={modelType === \\\"all\\\"}\\n    />\\n  );\\n\\n  const renderModelSection = (\\n    title: string,\\n    models: Model[],\\n    selectedModelType: ModelType,\\n  ) => {\\n    if (models.length === 0) return null;\\n    const [activeModels, deprecatedModels] = partitionDeprecated(models);\\n    return (\\n      <div data-testid={`${selectedModelType}-models-section`}>\\n        <div className=\\\"text-[13px] font-semibold text-muted-foreground\\\">\\n          {title}\\n        </div>\\n        <div className=\\\"flex flex-col gap-2 pt-4\\\">\\n          {activeModels.map((model) =>\\n            renderModelRow(model, selectedModelType),\\n          )}\\n        </div>\\n        {deprecatedModels.length > 0 && (\\n          <details\\n            className=\\\"pt-3\\\"\\n            data-testid={`${selectedModelType}-deprecated-disclosure`}\\n            open={showDeprecated}\\n            onToggle={(event) =>\\n              setShowDeprecated(\\n                (event.currentTarget as HTMLDetailsElement).open,\\n              )\\n            }\\n          >\\n            <summary\\n              className=\\\"text-xs font-medium text-muted-foreground hover:text-foreground cursor-pointer select-none\\\"\\n              data-testid={`${selectedModelType}-deprecated-summary`}\\n            >\\n              {deprecatedModels.length === 1\\n                ? t(\\\"modelProviders.showDeprecatedSingular\\\", {\\n                    defaultValue: \\\"Show 1 deprecated model\\\",\\n                  })\\n                : t(\\\"modelProviders.showDeprecated\\\", {\\n                    count: deprecatedModels.length,\\n                    defaultValue: \\\"Show {{count}} deprecated models\\\",\\n                  })}\\n            </summary>\\n            <div className=\\\"flex flex-col gap-2 pt-3\\\">\\n              {deprecatedModels.map((model) =>\\n                renderModelRow(model, selectedModelType),\\n              )}\\n            </div>\\n          </details>\\n        )}\\n      </div>\\n    );\\n  };\\n\\n  const providerOwnsEmptyState = hasProviderOwnedEmptyState(providerName);\\n  const isOllama =\\n    providerOwnsEmptyState && providerName?.toLowerCase() === \\\"ollama\\\";\\n  // Live-discovery providers have nothing to list until credentials are\\n  // configured; show a configure-credentials hint instead of the generic\\n  // \\\"no models\\\" state. Ollama keeps its own specialized empty state.\\n  const awaitsCredentialDiscovery =\\n    !!liveDiscovery && !isConfigured && !isOllama;\\n  // Use the unfiltered list for the empty-state check so an\\n  // ollama-no-models warning still fires when the search field happens to be\\n  // populated.\\n  const llmAvailableCount = modelsWithCustomDeployments.filter(\\n    (m) => m.metadata?.model_type === \\\"llm\\\",\\n  ).length;\\n  const embeddingAvailableCount = modelsWithCustomDeployments.filter(\\n    (m) => m.metadata?.model_type === \\\"embeddings\\\",\\n  ).length;\\n  const noModelsAvailable =\\n    (modelType === \\\"llm\\\" && llmAvailableCount === 0) ||\\n    (modelType === \\\"embeddings\\\" && embeddingAvailableCount === 0) ||\\n    (modelType === \\\"all\\\" && modelsWithCustomDeployments.length === 0);\\n\\n  const noModelsMatchQuery =\\n    !noModelsAvailable &&\\n    trimmedModelQueryLower.length > 0 &&\\n    llmModels.length === 0 &&\\n    embeddingModels.length === 0;\\n\\n  const showSearchInput =\\n    supportsCustomDeployments ||\\n    (!noModelsAvailable && modelsWithCustomDeployments.length > 0);\\n\\n  const searchInputLabel = supportsCustomDeployments\\n    ? t(\\\"modelProviders.searchOrAddDeployment\\\", {\\n        defaultValue: \\\"Search or add a deployment name\u2026\\\",\\n      })\\n    : t(\\\"modelProviders.searchModels\\\", {\\n        defaultValue: \\\"Search models\u2026\\\",\\n      });\\n\\n  if (!canUseEnabledModels) {\\n    return (\\n      <div\\n        data-testid=\\\"model-provider-selection\\\"\\n        className=\\\"flex flex-col gap-3\\\"\\n      >\\n        {isEnabledModelsError ? (\\n          <div role=\\\"alert\\\" className=\\\"flex flex-col items-start gap-3\\\">\\n            <span>{t(\\\"modelProviders.errorUnexpected\\\")}</span>\\n            <Button\\n              type=\\\"button\\\"\\n              variant=\\\"outline\\\"\\n              size=\\\"sm\\\"\\n              onClick={() => void refetchEnabledModels()}\\n            >\\n              {t(\\\"common.retry\\\")}\\n            </Button>\\n          </div>\\n        ) : (\\n          <div role=\\\"status\\\" aria-live=\\\"polite\\\">\\n            {t(\\\"modelInput.loadingModels\\\")}\\n          </div>\\n        )}\\n      </div>\\n    );\\n  }\\n\\n  return (\\n    <div data-testid=\\\"model-provider-selection\\\" className=\\\"flex flex-col gap-6\\\">\\n      {supportsCustomDeployments ? (\\n        <p\\n          className=\\\"text-xs text-muted-foreground leading-relaxed\\\"\\n          data-testid=\\\"custom-deployment-hint\\\"\\n        >\\n          {t(\\\"modelProviders.customDeploymentHint\\\", {\\n            defaultValue:\\n              \\\"Use your Azure AI Foundry deployment names from the portal (not catalog model IDs). Search or type a name to add one.\\\",\\n          })}\\n        </p>\\n      ) : null}\\n      {showSearchInput && (\\n        <Input\\n          icon=\\\"Search\\\"\\n          value={modelQuery}\\n          onChange={(event) => setModelQuery(event.target.value)}\\n          placeholder={searchInputLabel}\\n          aria-label={searchInputLabel}\\n          data-testid=\\\"model-search-input\\\"\\n        />\\n      )}\\n      {canAddCustomDeployment ? (\\n        <div className=\\\"flex flex-col gap-2\\\">\\n          {addableDeploymentTypes.map((deploymentType) => (\\n            <Button\\n              key={deploymentType}\\n              type=\\\"button\\\"\\n              variant=\\\"outline\\\"\\n              size=\\\"sm\\\"\\n              className=\\\"w-full justify-start\\\"\\n              data-testid={\\n                modelType === \\\"all\\\"\\n                  ? `add-custom-${deploymentType}-deployment-button`\\n                  : \\\"add-custom-deployment-button\\\"\\n              }\\n              onClick={() => {\\n                onModelToggle(trimmedModelQuery, true, deploymentType);\\n                setModelQuery(\\\"\\\");\\n              }}\\n            >\\n              <ForwardedIconComponent name=\\\"Plus\\\" className=\\\"mr-2 h-4 w-4\\\" />\\n              {modelType === \\\"all\\\"\\n                ? deploymentType === \\\"llm\\\"\\n                  ? t(\\\"modelProviders.addLanguageDeployment\\\", {\\n                      name: trimmedModelQuery,\\n                      defaultValue:\\n                        'Add deployment \\\"{{name}}\\\" as language model',\\n                    })\\n                  : t(\\\"modelProviders.addEmbeddingDeployment\\\", {\\n                      name: trimmedModelQuery,\\n                      defaultValue:\\n                        'Add deployment \\\"{{name}}\\\" as embedding model',\\n                    })\\n                : t(\\\"modelProviders.addDeployment\\\", {\\n                    name: trimmedModelQuery,\\n                    defaultValue: 'Add deployment \\\"{{name}}\\\"',\\n                  })}\\n            </Button>\\n          ))}\\n        </div>\\n      ) : null}\\n      {noModelsMatchQuery && !canAddCustomDeployment ? (\\n        <div\\n          className=\\\"text-muted-foreground px-1 py-2 text-sm\\\"\\n          data-testid=\\\"model-search-empty\\\"\\n        >\\n          {t(\\\"modelProviders.noModelsMatch\\\", {\\n            defaultValue: \\\"No models match your search.\\\",\\n          })}\\n        </div>\\n      ) : null}\\n      {isOllama && noModelsAvailable ? (\\n        <div className=\\\"flex flex-col items-center justify-center p-8 text-center border border-dashed rounded-lg bg-muted/30\\\">\\n          <ForwardedIconComponent\\n            name=\\\"Info\\\"\\n            className=\\\"w-10 h-10 mb-4 text-muted-foreground\\\"\\n          />\\n          <h3 className=\\\"mb-2 text-sm font-semibold text-foreground\\\">\\n            {t(\\\"modelProviders.noModelsAvailable\\\")}\\n          </h3>\\n          <p className=\\\"max-w-[300px] text-xs text-muted-foreground leading-relaxed\\\">\\n            {modelType === \\\"llm\\\"\\n              ? t(\\\"modelProviders.ollamaNoModelsLlm\\\")\\n              : modelType === \\\"embeddings\\\"\\n                ? t(\\\"modelProviders.ollamaNoModelsEmbeddings\\\")\\n                : t(\\\"modelProviders.ollamaNoModelsAll\\\")}\\n          </p>\\n          <a\\n            href=\\\"https://ollama.com/library\\\"\\n            target=\\\"_blank\\\"\\n            rel=\\\"noreferrer\\\"\\n            className=\\\"mt-6 text-xs font-medium text-primary underline underline-offset-4 hover:opacity-80 transition-opacity\\\"\\n          >\\n            {t(\\\"modelProviders.checkOllamaLibrary\\\")}\\n          </a>\\n        </div>\\n      ) : awaitsCredentialDiscovery && noModelsAvailable ? (\\n        <div\\n          className=\\\"flex flex-col items-center justify-center p-8 text-center border border-dashed rounded-lg bg-muted/30\\\"\\n          data-testid=\\\"live-discovery-empty-state\\\"\\n        >\\n          <ForwardedIconComponent\\n            name=\\\"Info\\\"\\n            className=\\\"w-10 h-10 mb-4 text-muted-foreground\\\"\\n          />\\n          <h3 className=\\\"mb-2 text-sm font-semibold text-foreground\\\">\\n            {t(\\\"modelProviders.liveDiscoveryTitle\\\", {\\n              defaultValue: \\\"No models yet\\\",\\n            })}\\n          </h3>\\n          <p className=\\\"max-w-[300px] text-xs text-muted-foreground leading-relaxed\\\">\\n            {t(\\\"modelProviders.liveDiscoveryHint\\\", {\\n              provider: providerName,\\n              defaultValue:\\n                \\\"{{provider}} models are discovered from your account once credentials are configured. Save your credentials above to load the available models.\\\",\\n            })}\\n          </p>\\n        </div>\\n      ) : (\\n        <>\\n          {modelType === \\\"all\\\" ? (\\n            <>\\n              {renderModelSection(\\n                t(\\\"modelProviders.languageModels\\\"),\\n                llmModels,\\n                \\\"llm\\\",\\n              )}\\n              {renderModelSection(\\n                t(\\\"modelProviders.embeddingModels\\\"),\\n                embeddingModels,\\n                \\\"embeddings\\\",\\n              )}\\n            </>\\n          ) : modelType === \\\"llm\\\" ? (\\n            renderModelSection(\\n              t(\\\"modelProviders.languageModels\\\"),\\n              llmModels,\\n              \\\"llm\\\",\\n            )\\n          ) : (\\n            renderModelSection(\\n              t(\\\"modelProviders.embeddingModels\\\"),\\n              embeddingModels,\\n              \\\"embeddings\\\",\\n            )\\n          )}\\n        </>\\n      )}\\n    </div>\\n  );\\n};\\n\\nexport default ModelSelection;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/ProviderConfigurationForm.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ccbe3a7660dc4c39853e2c77f3313d53541183806765256e529a9ae09f38a3e\",\"content\":\"import { useEffect, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport ShadTooltip from \\\"@/components/common/shadTooltipComponent\\\";\\nimport MultiselectComponent from \\\"@/components/core/parameterRenderComponent/components/multiselectComponent\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport { Input } from \\\"@/components/ui/input\\\";\\nimport type { ProviderVariable } from \\\"@/constants/providerConstants\\\";\\nimport useAlertStore from \\\"@/stores/alertStore\\\";\\nimport DisconnectWarning from \\\"./DisconnectWarning\\\";\\nimport type { Provider } from \\\"./types\\\";\\n\\nconst PROVIDER_KEY_PREVIEW: Record<\\n  string,\\n  { prefix: string; totalLength: number }\\n> = {\\n  OpenAI: { prefix: \\\"sk-\\\", totalLength: 164 },\\n  Anthropic: { prefix: \\\"sk-ant-\\\", totalLength: 108 },\\n  \\\"Google Generative AI\\\": { prefix: \\\"AIza\\\", totalLength: 39 },\\n  \\\"IBM watsonx\\\": { prefix: \\\"\\\", totalLength: 44 },\\n};\\n\\nconst getMaskedKeyPreview = (providerName: string): string => {\\n  const config = PROVIDER_KEY_PREVIEW[providerName] || {\\n    prefix: \\\"\\\",\\n    totalLength: 40,\\n  };\\n  const maskedLength = Math.max(config.totalLength - config.prefix.length, 8);\\n  return `${config.prefix}${\\\"\u2022\\\".repeat(maskedLength)}`;\\n};\\n\\nexport interface ProviderConfigurationFormProps {\\n  selectedProvider: Provider | null;\\n  providerVariables: ProviderVariable[];\\n  variableValues: Record<string, string>;\\n  isVariableConfigured: (key: string) => boolean;\\n  getConfiguredValue: (key: string) => string | null;\\n  onVariableChange: (key: string, value: string) => void;\\n  onSave: () => void;\\n  onActivate: () => void;\\n  onDisconnect: () => void;\\n  isSaving: boolean;\\n  isPending: boolean;\\n  isDeleting: boolean;\\n  isFetchingModels: boolean;\\n  validationFailed: boolean;\\n  validationState: \\\"idle\\\" | \\\"validating\\\" | \\\"valid\\\" | \\\"invalid\\\";\\n  validationError: string | null;\\n  canSave: boolean;\\n  requiresConfiguration: boolean;\\n  isFetchingAfterDisconnect: boolean;\\n}\\n\\n// Generate a stable random placeholder for a given variable type\\nconst getPlaceholder = (\\n  variableName: string,\\n  provider: string,\\n  t: (key: string, opts?: Record<string, string>) => string,\\n) => {\\n  const name = variableName.toLowerCase();\\n  const providerLower = provider.toLowerCase();\\n\\n  if (providerLower === \\\"ollama\\\" && name.includes(\\\"url\\\")) {\\n    return \\\"http://localhost:11434\\\";\\n  }\\n\\n  if (\\n    name.includes(\\\"api key\\\") ||\\n    name.includes(\\\"apikey\\\") ||\\n    name.includes(\\\"token\\\")\\n  ) {\\n    if (providerLower.includes(\\\"anthropic\\\")) return \\\"sk-ant-...\\\";\\n    if (providerLower.includes(\\\"google\\\")) return \\\"AIza...\\\";\\n    if (providerLower.includes(\\\"openai\\\")) return \\\"sk-...\\\";\\n  }\\n\\n  return t(\\\"modelProviders.enterVariable\\\", { variableName });\\n};\\n\\nconst ProviderConfigurationForm = ({\\n  selectedProvider,\\n  providerVariables,\\n  variableValues,\\n  isVariableConfigured,\\n  getConfiguredValue,\\n  onVariableChange,\\n  onSave,\\n  onActivate,\\n  onDisconnect,\\n  isSaving,\\n  isPending,\\n  isDeleting,\\n  isFetchingModels,\\n  validationFailed,\\n  validationState,\\n  validationError,\\n  canSave,\\n  requiresConfiguration,\\n  isFetchingAfterDisconnect,\\n}: ProviderConfigurationFormProps) => {\\n  const { t } = useTranslation();\\n  const [showDisconnectWarning, setShowDisconnectWarning] = useState(false);\\n  const [editingSecret, setEditingSecret] = useState<Record<string, boolean>>(\\n    {},\\n  );\\n\\n  // True during validation, saving, and the post-save model refetch\\n  const isLoading =\\n    isSaving || validationState === \\\"validating\\\" || isFetchingModels;\\n\\n  const setErrorData = useAlertStore((state) => state.setErrorData);\\n\\n  useEffect(() => {\\n    if (validationState === \\\"invalid\\\" && validationError) {\\n      setErrorData({\\n        title: t(\\\"modelProviders.validationFailed\\\"),\\n        list: [validationError],\\n      });\\n    }\\n  }, [validationState, validationError]);\\n\\n  const isAlreadyConfigured = providerVariables\\n    .filter((v) => v.required)\\n    .every((v) => isVariableConfigured(v.variable_key));\\n\\n  const isSingleVariableProvider = providerVariables.length === 1;\\n\\n  if (!selectedProvider) return null;\\n\\n  return (\\n    <div className=\\\"flex flex-col gap-1 px-4 pt-4\\\">\\n      <div className=\\\"flex flex-row gap-1 min-w-[300px]\\\">\\n        <span\\n          id=\\\"provider-single-variable-label\\\"\\n          className=\\\"text-[13px] font-semibold mr-auto\\\"\\n        >\\n          {isSingleVariableProvider ? (\\n            <>\\n              {providerVariables[0].variable_name}\\n              {providerVariables[0].required && (\\n                <span className=\\\"text-destructive ml-1\\\">*</span>\\n              )}\\n            </>\\n          ) : (\\n            `${selectedProvider.provider || t(\\\"modelProviders.unknownProvider\\\")} ${requiresConfiguration && ` ${t(\\\"modelProviders.configuration\\\")}`}`\\n          )}\\n        </span>\\n      </div>\\n      <span className=\\\"text-[13px] text-muted-foreground pt-1 pb-2\\\">\\n        {requiresConfiguration ? (\\n          <>\\n            {t(\\\"modelProviders.configurePrefix\\\")}{\\\" \\\"}\\n            {selectedProvider.api_docs_url ? (\\n              <a\\n                href={selectedProvider.api_docs_url}\\n                target=\\\"_blank\\\"\\n                rel=\\\"noopener noreferrer\\\"\\n                className=\\\"underline hover:text-primary rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\\\"\\n              >\\n                {t(\\\"modelProviders.credentialsLink\\\", {\\n                  provider: selectedProvider.provider,\\n                })}\\n              </a>\\n            ) : (\\n              <span>\\n                {t(\\\"modelProviders.credentialsLink\\\", {\\n                  provider: selectedProvider.provider,\\n                })}\\n              </span>\\n            )}{\\\" \\\"}\\n            {t(\\\"modelProviders.toEnableModels\\\")}\\n          </>\\n        ) : (\\n          <>\\n            {t(\\\"modelProviders.activateToEnable\\\", {\\n              provider: selectedProvider.provider,\\n            })}\\n          </>\\n        )}\\n      </span>\\n      {requiresConfiguration ? (\\n        <div className=\\\"flex flex-col gap-3\\\">\\n          {providerVariables.map((variable) => {\\n            const isConfigured = isVariableConfigured(variable.variable_key);\\n            const hasNewValue = variableValues[variable.variable_key]?.trim();\\n            const isEditing = editingSecret[variable.variable_key];\\n            const inputId = `provider-variable-${variable.variable_key}`;\\n            // Single-variable providers render their only label as the form\\n            // heading, so the control is named via aria-labelledby instead.\\n            const labelId = isSingleVariableProvider\\n              ? \\\"provider-single-variable-label\\\"\\n              : `provider-variable-label-${variable.variable_key}`;\\n\\n            return (\\n              <div key={variable.variable_key} className=\\\"flex flex-col gap-1\\\">\\n                {!isSingleVariableProvider && (\\n                  <label\\n                    id={labelId}\\n                    // The options branch renders a multiselect with no id \u2014\\n                    // only the text-input branch has a target for htmlFor.\\n                    htmlFor={\\n                      variable.options && variable.options.length > 0\\n                        ? undefined\\n                        : inputId\\n                    }\\n                    className=\\\"text-[12px] font-medium text-muted-foreground\\\"\\n                  >\\n                    {variable.variable_name}\\n                    {variable.required && (\\n                      <span className=\\\"text-destructive ml-1\\\">*</span>\\n                    )}\\n                  </label>\\n                )}\\n                {variable.options && variable.options.length > 0 ? (\\n                  // Render dropdown for variables with predefined options\\n                  <div className=\\\"relative\\\">\\n                    <MultiselectComponent\\n                      id={variable.variable_key}\\n                      ariaLabelledBy={labelId}\\n                      editNode={false}\\n                      disabled={isSaving || isDeleting}\\n                      value={\\n                        variableValues[variable.variable_key]\\n                          ? [variableValues[variable.variable_key]]\\n                          : isConfigured &&\\n                              getConfiguredValue(variable.variable_key)\\n                            ? [\\n                                getConfiguredValue(\\n                                  variable.variable_key,\\n                                ) as string,\\n                              ]\\n                            : []\\n                      }\\n                      options={variable.options}\\n                      combobox={variable.combobox}\\n                      hideOnSelection={true}\\n                      handleOnNewValue={(val) => {\\n                        const newArray = val.value as string[];\\n                        if (newArray && newArray.length > 0) {\\n                          onVariableChange(\\n                            variable.variable_key,\\n                            newArray[newArray.length - 1],\\n                          );\\n                        } else {\\n                          onVariableChange(variable.variable_key, \\\"\\\");\\n                        }\\n                      }}\\n                    />\\n                    {!isLoading && (\\n                      <>\\n                        {validationState === \\\"invalid\\\" && (\\n                          <span className=\\\"absolute w-4 h-4 right-9 top-1/2 -translate-y-1/2 pointer-events-auto\\\">\\n                            <ShadTooltip\\n                              content={validationError}\\n                              side=\\\"top\\\"\\n                              styleClasses=\\\"text-destructive border-destructive\\\"\\n                            >\\n                              <div>\\n                                <ForwardedIconComponent\\n                                  name=\\\"X\\\"\\n                                  className=\\\"h-4 w-4 text-destructive cursor-default\\\"\\n                                />\\n                              </div>\\n                            </ShadTooltip>\\n                          </span>\\n                        )}\\n                        {validationState !== \\\"invalid\\\" &&\\n                          (validationState === \\\"valid\\\" ||\\n                            (isConfigured && !hasNewValue)) && (\\n                            <span className=\\\"absolute right-8 top-1/2 -translate-y-1/2 text-accent-emerald-foreground pointer-events-none\\\">\\n                              <ForwardedIconComponent\\n                                name=\\\"Check\\\"\\n                                className=\\\"h-4 w-4\\\"\\n                              />\\n                            </span>\\n                          )}\\n                      </>\\n                    )}\\n                  </div>\\n                ) : (\\n                  // Render input for text/secret variables\\n                  <Input\\n                    id={inputId}\\n                    aria-labelledby={\\n                      isSingleVariableProvider ? labelId : undefined\\n                    }\\n                    aria-invalid={\\n                      (validationState === \\\"invalid\\\" && variable.required) ||\\n                      undefined\\n                    }\\n                    aria-describedby={\\n                      validationState === \\\"invalid\\\" && validationError\\n                        ? \\\"provider-validation-error\\\"\\n                        : undefined\\n                    }\\n                    data-testid={`provider-variable-input-${variable.variable_key}`}\\n                    placeholder={getPlaceholder(\\n                      variable.variable_name,\\n                      selectedProvider.provider,\\n                      t,\\n                    )}\\n                    value={\\n                      isConfigured &&\\n                      variable.is_secret &&\\n                      !isEditing &&\\n                      !hasNewValue\\n                        ? getMaskedKeyPreview(selectedProvider.provider)\\n                        : variable.variable_key in variableValues\\n                          ? variableValues[variable.variable_key]\\n                          : isConfigured && !variable.is_secret\\n                            ? (getConfiguredValue(variable.variable_key) ?? \\\"\\\")\\n                            : \\\"\\\"\\n                    }\\n                    type={\\n                      variable.is_secret && (isEditing || hasNewValue)\\n                        ? \\\"password\\\"\\n                        : \\\"text\\\"\\n                    }\\n                    onChange={(e) => {\\n                      onVariableChange(variable.variable_key, e.target.value);\\n                    }}\\n                    onFocus={() => {\\n                      if (isConfigured && variable.is_secret && !hasNewValue) {\\n                        setEditingSecret((prev) => ({\\n                          ...prev,\\n                          [variable.variable_key]: true,\\n                        }));\\n                        onVariableChange(variable.variable_key, \\\"\\\");\\n                      }\\n                    }}\\n                    onBlur={() => {\\n                      if (!variableValues[variable.variable_key]) {\\n                        setEditingSecret((prev) => ({\\n                          ...prev,\\n                          [variable.variable_key]: false,\\n                        }));\\n                      }\\n                    }}\\n                    endIcon={\\n                      !isLoading && validationState === \\\"invalid\\\" ? (\\n                        <ShadTooltip\\n                          content={validationError}\\n                          side=\\\"top\\\"\\n                          styleClasses=\\\"text-destructive border-destructive\\\"\\n                        >\\n                          <div>\\n                            <ForwardedIconComponent\\n                              name=\\\"X\\\"\\n                              className=\\\"h-4 w-4 text-destructive cursor-default\\\"\\n                            />\\n                          </div>\\n                        </ShadTooltip>\\n                      ) : !isLoading &&\\n                        (validationState === \\\"valid\\\" ||\\n                          (isConfigured && !hasNewValue && !isEditing)) ? (\\n                        <ForwardedIconComponent\\n                          name=\\\"Check\\\"\\n                          className=\\\"h-4 w-4 text-accent-emerald-foreground pointer-events-none\\\"\\n                        />\\n                      ) : undefined\\n                    }\\n                  />\\n                )}\\n              </div>\\n            );\\n          })}\\n          {validationState === \\\"invalid\\\" && validationError && (\\n            <p\\n              id=\\\"provider-validation-error\\\"\\n              role=\\\"alert\\\"\\n              className=\\\"field-invalid static\\\"\\n            >\\n              {validationError}\\n            </p>\\n          )}\\n          {/* Save button */}\\n          <div className=\\\"flex justify-end mt-2 gap-2\\\">\\n            {selectedProvider.is_enabled && (\\n              <Button\\n                variant=\\\"destructive\\\"\\n                size=\\\"sm\\\"\\n                data-testid=\\\"provider-disconnect-button\\\"\\n                onClick={() => setShowDisconnectWarning(true)}\\n                loading={isDeleting || isFetchingAfterDisconnect}\\n                disabled={isDeleting || isFetchingAfterDisconnect || isSaving}\\n              >\\n                {t(\\\"modelProviders.disconnectButton\\\")}\\n              </Button>\\n            )}\\n            <Button\\n              onClick={onSave}\\n              size=\\\"sm\\\"\\n              data-testid=\\\"provider-save-button\\\"\\n              loading={isLoading || isFetchingModels}\\n              disabled={!canSave || isLoading || isFetchingModels}\\n            >\\n              {validationFailed\\n                ? t(\\\"modelProviders.retrySaveButton\\\")\\n                : isAlreadyConfigured\\n                  ? t(\\\"modelProviders.replaceButton\\\")\\n                  : t(\\\"modelProviders.saveButton\\\")}\\n            </Button>\\n          </div>\\n        </div>\\n      ) : (\\n        <div className=\\\"flex flex-col gap-2\\\">\\n          <Button\\n            onClick={onActivate}\\n            loading={isPending}\\n            disabled={selectedProvider.is_enabled}\\n          >\\n            {selectedProvider.is_enabled\\n              ? t(\\\"modelProviders.activatedButton\\\", {\\n                  provider: selectedProvider.provider,\\n                })\\n              : t(\\\"modelProviders.activateButton\\\", {\\n                  provider: selectedProvider.provider,\\n                })}\\n          </Button>\\n          {selectedProvider.is_enabled && (\\n            <Button\\n              variant=\\\"destructive\\\"\\n              data-testid=\\\"provider-deactivate-button\\\"\\n              onClick={() => setShowDisconnectWarning(true)}\\n              disabled={isDeleting || isPending}\\n            >\\n              {t(\\\"modelProviders.deactivateButton\\\", {\\n                provider: selectedProvider.provider,\\n              })}\\n            </Button>\\n          )}\\n        </div>\\n      )}\\n\\n      <DisconnectWarning\\n        show={showDisconnectWarning}\\n        message={\\n          requiresConfiguration\\n            ? t(\\\"modelProviders.disconnectApiKeyWarning\\\")\\n            : t(\\\"modelProviders.deactivateWarning\\\", {\\n                provider: selectedProvider.provider,\\n              })\\n        }\\n        onCancel={() => setShowDisconnectWarning(false)}\\n        onConfirm={() => {\\n          onDisconnect();\\n          setShowDisconnectWarning(false);\\n        }}\\n        isLoading={isDeleting}\\n      />\\n    </div>\\n  );\\n};\\n\\nexport default ProviderConfigurationForm;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/ProviderList.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8cc89cb2a09acc89f5646c7f73629ba51f42ad11966d3fe1663024361c23f5ee\",\"content\":\"import { useMemo } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport LoadingTextComponent from \\\"@/components/common/loadingTextComponent\\\";\\nimport type { ProviderScopeParams } from \\\"@/controllers/API/helpers/provider-scope\\\";\\nimport { useGetModelProviders } from \\\"@/controllers/API/queries/models/use-get-model-providers\\\";\\nimport CustomModelProvidersEmptyState from \\\"@/customization/components/custom-model-providers-empty-state\\\";\\nimport type { ModelTypeFilter } from \\\"@/types/models\\\";\\nimport ProviderListItem from \\\"./ProviderListItem\\\";\\nimport { Provider } from \\\"./types\\\";\\n\\nexport interface ProviderListProps extends ProviderScopeParams {\\n  modelType: ModelTypeFilter;\\n  onProviderSelect?: (provider: Provider) => void;\\n  selectedProviderName?: string | null;\\n  /** Case-insensitive substring filter applied to the provider name. */\\n  query?: string;\\n}\\n\\nconst ProviderList = ({\\n  modelType,\\n  onProviderSelect,\\n  selectedProviderName,\\n  query,\\n  flowId,\\n  projectId,\\n}: ProviderListProps) => {\\n  const { t } = useTranslation();\\n  const {\\n    data: rawProviders = [],\\n    isLoading,\\n    isFetching,\\n    fetchStatus,\\n    isError,\\n  } = useGetModelProviders({\\n    includeDeprecated: true,\\n    flowId,\\n    projectId,\\n    purpose: \\\"configure\\\",\\n  });\\n\\n  const trimmedQuery = (query ?? \\\"\\\").trim().toLowerCase();\\n\\n  const filteredProviders: Provider[] = useMemo(() => {\\n    const matchesQuery = (providerName: string): boolean =>\\n      trimmedQuery.length === 0 ||\\n      providerName.toLowerCase().includes(trimmedQuery);\\n\\n    return rawProviders\\n      .filter((provider) => matchesQuery(provider.provider))\\n      .map((provider) => {\\n        const matchingModels =\\n          provider?.models?.filter((model) =>\\n            modelType === \\\"all\\\"\\n              ? true\\n              : model?.metadata?.model_type === modelType,\\n          ) || [];\\n\\n        return {\\n          provider: provider.provider,\\n          icon: provider.icon,\\n          is_enabled: provider.is_enabled,\\n          is_configured: provider.is_configured,\\n          model_count: matchingModels.length,\\n          models: matchingModels,\\n          api_docs_url: provider.api_docs_url,\\n          live_discovery: provider.live_discovery,\\n        };\\n      });\\n  }, [rawProviders, modelType, trimmedQuery]);\\n\\n  const handleProviderSelect = (provider: Provider) => {\\n    onProviderSelect?.(provider);\\n  };\\n\\n  const isLoadingProviders =\\n    isLoading || isFetching || fetchStatus === \\\"paused\\\";\\n\\n  if (isLoadingProviders) {\\n    return (\\n      <div\\n        className=\\\"text-muted-foreground px-4 py-2\\\"\\n        data-testid=\\\"provider-list-loading\\\"\\n      >\\n        <LoadingTextComponent text={t(\\\"modelProviders.loadingProviders\\\")} />\\n      </div>\\n    );\\n  }\\n\\n  if (isError) {\\n    return (\\n      <div\\n        role=\\\"alert\\\"\\n        className=\\\"text-muted-foreground px-4 py-2 text-sm\\\"\\n        data-testid=\\\"provider-list-error\\\"\\n      >\\n        {t(\\\"modelProviders.errorUnexpected\\\")}\\n      </div>\\n    );\\n  }\\n\\n  if (trimmedQuery.length > 0 && filteredProviders.length === 0) {\\n    return (\\n      <div\\n        className=\\\"text-muted-foreground px-4 py-2 text-sm\\\"\\n        data-testid=\\\"provider-list-empty\\\"\\n      >\\n        {t(\\\"modelProviders.noProvidersMatch\\\", {\\n          defaultValue: \\\"No providers match your search.\\\",\\n        })}\\n      </div>\\n    );\\n  }\\n\\n  return (\\n    <CustomModelProvidersEmptyState\\n      kind=\\\"providers\\\"\\n      show={filteredProviders.length === 0}\\n    >\\n      <div className=\\\"flex flex-col gap-1\\\" data-testid=\\\"provider-list\\\">\\n        {filteredProviders.map((provider) => (\\n          <ProviderListItem\\n            key={provider.provider}\\n            provider={provider}\\n            showIcon={selectedProviderName !== null}\\n            isSelected={selectedProviderName === provider.provider}\\n            onSelect={handleProviderSelect}\\n          />\\n        ))}\\n      </div>\\n    </CustomModelProvidersEmptyState>\\n  );\\n};\\n\\nexport default ProviderList;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/ProviderListItem.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a4f33d2f310b6dc88849a2c1718c5fe614e451038fcceed2b624c97016b4d85d\",\"content\":\"import { ForwardedIconComponent } from \\\"@/components/common/genericIconComponent\\\";\\nimport { Badge } from \\\"@/components/ui/badge\\\";\\nimport { cn } from \\\"@/utils/utils\\\";\\nimport { Provider } from \\\"./types\\\";\\n\\nexport interface ProviderListItemProps {\\n  provider: Provider;\\n  isSelected?: boolean;\\n  onSelect: (provider: Provider) => void;\\n  showIcon?: boolean;\\n}\\n\\nconst ProviderListItem = ({\\n  provider,\\n  isSelected,\\n  onSelect,\\n  showIcon,\\n}: ProviderListItemProps) => {\\n  const isEnabled = provider.is_enabled;\\n  const isConfigured = provider.is_configured;\\n  const isActive = isEnabled || isConfigured;\\n\\n  return (\\n    <button\\n      type=\\\"button\\\"\\n      data-testid={`provider-item-${provider.provider}`}\\n      aria-pressed={isSelected}\\n      className={cn(\\n        \\\"flex w-full items-center justify-between rounded-lg px-2 py-3 text-left transition-colors hover:bg-muted/50 cursor-pointer focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring focus-visible:ring-offset-2\\\",\\n        isSelected && \\\"bg-muted/50\\\",\\n      )}\\n      onClick={() => onSelect(provider)}\\n    >\\n      <div className=\\\"flex min-w-0 flex-1 items-center gap-3\\\">\\n        <ForwardedIconComponent\\n          name={provider.icon || \\\"Bot\\\"}\\n          className={cn(\\n            \\\"h-5 w-5 flex-shrink-0 transition-all\\\",\\n            !isActive && \\\"opacity-50 grayscale\\\",\\n          )}\\n        />\\n        <div className=\\\"flex min-w-0 flex-1 items-center gap-3\\\">\\n          <span\\n            className={cn(\\n              \\\"truncate text-sm font-medium\\\",\\n              !isActive && \\\"text-muted-foreground\\\",\\n            )}\\n          >\\n            {provider.provider}\\n          </span>\\n          {provider.model_count !== undefined && isActive && (\\n            <Badge\\n              variant={isSelected ? \\\"secondary\\\" : \\\"secondaryStatic\\\"}\\n              className=\\\"text-xs whitespace-nowrap mr-2\\\"\\n              size=\\\"sq\\\"\\n            >\\n              {provider.model_count}{\\\" \\\"}\\n              {provider.model_count === 1 ? \\\"model\\\" : \\\"models\\\"}\\n            </Badge>\\n          )}\\n        </div>\\n      </div>\\n      {!showIcon && (\\n        <ForwardedIconComponent\\n          name={isActive ? \\\"check\\\" : \\\"Plus\\\"}\\n          className={cn(\\n            \\\"h-4 w-4\\\",\\n            !isActive ? \\\"text-muted-foreground\\\" : \\\"text-status-green\\\",\\n          )}\\n        />\\n      )}\\n    </button>\\n  );\\n};\\n\\nexport default ProviderListItem;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/components/types.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"030cbb647296038ef483b789c56227cca38bc4a216fa511595dd4520d90e1d84\",\"content\":\"/** Represents a single AI model (LLM or embedding) */\\nexport type Model = {\\n  model_name: string;\\n  /** Arbitrary metadata including icon, model_type, deprecated, default flags */\\n  // biome-ignore lint/suspicious/noExplicitAny: legacy\\n  metadata: Record<string, any>;\\n};\\n\\n/** Represents a model provider (e.g., OpenAI, Anthropic) */\\nexport type Provider = {\\n  provider: string;\\n  icon?: string;\\n  is_enabled: boolean;\\n  is_configured?: boolean;\\n  model_count?: number;\\n  models?: Model[];\\n  api_docs_url?: string;\\n  /** True when the model list is discovered from the provider's endpoint\\n   *  after credentials are configured (e.g. IBM WatsonX, OpenRouter, vLLM). */\\n  live_discovery?: boolean;\\n};\\n\\n/** Map of provider -> model_name -> enabled status */\\nexport type EnabledModelsData = {\\n  enabled_models?: Record<string, Record<string, boolean>>;\\n};\\n\\n/** Currently selected default model configuration */\\nexport type DefaultModelData = {\\n  default_model?: {\\n    model_name: string;\\n    provider: string;\\n    model_type: string;\\n  } | null;\\n};\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/modals/modelProviderModal/hooks/useModelToggleQueue.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ba4920bc4c1455775cff0d775d9b9ce4bfd9efa0d1b24d643157a339cb0817c\",\"content\":\"import { useQueryClient } from \\\"@tanstack/react-query\\\";\\nimport { useCallback, useEffect, useRef } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport type { ProviderScopeParams } from \\\"@/controllers/API/helpers/provider-scope\\\";\\nimport { isSettledSuccessfulQuery } from \\\"@/controllers/API/helpers/query-cache\\\";\\nimport {\\n  EnabledModelsResponse,\\n  getEnabledModelsQueryKey,\\n  useGetEnabledModels,\\n} from \\\"@/controllers/API/queries/models/use-get-enabled-models\\\";\\nimport {\\n  ModelStatusUpdate,\\n  useUpdateEnabledModels,\\n} from \\\"@/controllers/API/queries/models/use-update-enabled-models\\\";\\nimport { useDebounce } from \\\"@/hooks/use-debounce\\\";\\nimport { useRefreshModelInputs } from \\\"@/hooks/use-refresh-model-inputs\\\";\\nimport useAlertStore from \\\"@/stores/alertStore\\\";\\nimport type { ModelType } from \\\"@/types/models\\\";\\n\\n// Extracted from useProviderConfiguration.ts to keep the toggle-queue\\n// concerns (overlay buffer, unsent buffer, debounced flush, awaitable\\n// flush, re-overlay effect, optimistic cache management) in a single\\n// focused module. The parent hook now owns only variable CRUD and\\n// provider lifecycle \u2014 the two responsibilities no longer share a file.\\n\\nconst getErrorMessage = (error: unknown): string | undefined => {\\n  const e = error as {\\n    response?: { data?: { detail?: string } };\\n    message?: string;\\n  };\\n  return e?.response?.data?.detail || e?.message;\\n};\\n\\ntype ToggleMap = Map<string, ModelStatusUpdate>;\\n\\nconst getToggleContextIdentity = (\\n  providerName: string | null | undefined,\\n  flowId?: string,\\n  projectId?: string,\\n): string =>\\n  JSON.stringify([providerName ?? null, flowId ?? null, projectId ?? null]);\\n\\nconst getToggleIdentity = (\\n  contextIdentity: string,\\n  providerName: string,\\n  modelName: string,\\n  modelType: ModelType,\\n): string =>\\n  JSON.stringify([contextIdentity, providerName, modelType, modelName]);\\n\\nconst getToggleEnabled = (\\n  data: EnabledModelsResponse,\\n  update: ModelStatusUpdate,\\n): boolean => {\\n  const typedProvider = data.enabled_models_by_type?.[update.provider];\\n  if (typedProvider !== undefined) {\\n    return typedProvider[update.model_type]?.[update.model_id] ?? false;\\n  }\\n  return data.enabled_models[update.provider]?.[update.model_id] ?? false;\\n};\\n\\nconst applyToggleToEnabledModels = (\\n  data: EnabledModelsResponse,\\n  update: ModelStatusUpdate,\\n): EnabledModelsResponse => {\\n  const {\\n    provider,\\n    model_id: modelName,\\n    model_type: modelType,\\n    enabled,\\n  } = update;\\n  const typedProvider = data.enabled_models_by_type?.[provider];\\n\\n  // A provider without a typed map is using the legacy response contract even\\n  // if another provider in the same response is typed. Preserve its flat\\n  // optimistic update while still sending model_type to the mutation endpoint.\\n  if (typedProvider === undefined) {\\n    return {\\n      ...data,\\n      enabled_models: {\\n        ...data.enabled_models,\\n        [provider]: {\\n          ...(data.enabled_models[provider] ?? {}),\\n          [modelName]: enabled,\\n        },\\n      },\\n    };\\n  }\\n\\n  const otherType: ModelType = modelType === \\\"llm\\\" ? \\\"embeddings\\\" : \\\"llm\\\";\\n  const nextTypedProvider = {\\n    ...typedProvider,\\n    [modelType]: {\\n      ...(typedProvider[modelType] ?? {}),\\n      [modelName]: enabled,\\n    },\\n  };\\n  const flatEnabled =\\n    enabled || (nextTypedProvider[otherType]?.[modelName] ?? false);\\n\\n  return {\\n    ...data,\\n    enabled_models: {\\n      ...data.enabled_models,\\n      [provider]: {\\n        ...(data.enabled_models[provider] ?? {}),\\n        [modelName]: flatEnabled,\\n      },\\n    },\\n    enabled_models_by_type: {\\n      ...data.enabled_models_by_type,\\n      [provider]: nextTypedProvider,\\n    },\\n  };\\n};\\n\\nconst applyToggleMap = (\\n  data: EnabledModelsResponse,\\n  toggles: ToggleMap,\\n): EnabledModelsResponse => {\\n  let nextData = data;\\n  for (const update of toggles.values()) {\\n    nextData = applyToggleToEnabledModels(nextData, update);\\n  }\\n  return nextData;\\n};\\n\\nexport interface UseModelToggleQueueOptions extends ProviderScopeParams {\\n  /**\\n   * Provider whose models the user is toggling. ``null`` short-circuits all\\n   * handlers \u2014 useful while the modal is still resolving the selection.\\n   */\\n  providerName: string | null | undefined;\\n}\\n\\nexport interface UseModelToggleQueueReturn {\\n  handleModelToggle: (\\n    modelName: string,\\n    enabled: boolean,\\n    modelType: ModelType,\\n  ) => void;\\n  flushPendingChanges: () => Promise<void>;\\n}\\n\\ninterface ToggleBatch {\\n  updates: ModelStatusUpdate[];\\n  previousData: EnabledModelsResponse | undefined;\\n  togglesToSend: ToggleMap;\\n  queryKey: ReturnType<typeof getEnabledModelsQueryKey>;\\n  flowId?: string;\\n  projectId?: string;\\n}\\n\\ninterface ActiveToggleContext {\\n  identity: string;\\n  queryKey: ReturnType<typeof getEnabledModelsQueryKey>;\\n  flowId?: string;\\n  projectId?: string;\\n}\\n\\n/**\\n * Coordinated optimistic-update queue for model enable/disable toggles.\\n *\\n * Two refs back the queue, each with a single responsibility:\\n *\\n *   - ``overlayToggles`` \u2014 the union of every toggle the user has made\\n *     whose change has not yet been confirmed by the server. The\\n *     re-overlay effect re-applies it whenever ``useGetEnabledModels``\\n *     emits new data, so any refetch which lands inside the debounce or\\n *     in-flight-mutation window can't overwrite the optimistic cache\\n *     with stale server state. Entries are drained per-key on\\n *     ``onSettled``/``onError`` \u2014 but only when the entry still matches\\n *     the value we sent (a user re-toggle mid-flight becomes a fresh\\n *     intent and must survive the clear).\\n *\\n *   - ``unsentToggles`` \u2014 the strict subset that has NOT been sent in a\\n *     mutation yet (or was re-toggled since the last send). It's drained\\n *     immediately at flush time so subsequent flushes don't resend the\\n *     same payload \u2014 without this split, mutation A's in-flight overlay\\n *     entries would be snapshotted into mutation B's payload, producing\\n *     duplicate requests with non-deterministic success/failure ordering.\\n */\\nexport const useModelToggleQueue = ({\\n  providerName,\\n  flowId,\\n  projectId,\\n}: UseModelToggleQueueOptions): UseModelToggleQueueReturn => {\\n  const queryClient = useQueryClient();\\n  const { t } = useTranslation();\\n  const setErrorData = useAlertStore((state) => state.setErrorData);\\n  const { mutate: updateEnabledModels, mutateAsync: updateEnabledModelsAsync } =\\n    useUpdateEnabledModels({ retry: 0 });\\n  const { refreshAllModelInputs } = useRefreshModelInputs();\\n  const providerScope = {\\n    flowId,\\n    projectId,\\n    purpose: \\\"configure\\\" as const,\\n  };\\n  const enabledModelsQueryKey = getEnabledModelsQueryKey(providerScope);\\n  const currentContextIdentity = getToggleContextIdentity(\\n    providerName,\\n    flowId,\\n    projectId,\\n  );\\n  const {\\n    data: enabledModelsData,\\n    isSuccess: isEnabledModelsSuccess,\\n    isFetching: isEnabledModelsFetching,\\n    isFetchedAfterMount: isEnabledModelsFetchedAfterMount,\\n    fetchStatus: enabledModelsFetchStatus,\\n  } = useGetEnabledModels(providerScope);\\n  const enabledModelsQueryIsFresh =\\n    !!enabledModelsData &&\\n    isEnabledModelsSuccess &&\\n    !isEnabledModelsFetching &&\\n    isEnabledModelsFetchedAfterMount &&\\n    enabledModelsFetchStatus === \\\"idle\\\";\\n  const enabledModelsIncludeProvider =\\n    !!providerName &&\\n    !!enabledModelsData &&\\n    Object.hasOwn(enabledModelsData.enabled_models, providerName);\\n\\n  const canMutateEnabledModels = useCallback(\\n    () =>\\n      enabledModelsQueryIsFresh &&\\n      enabledModelsIncludeProvider &&\\n      isSettledSuccessfulQuery(queryClient, enabledModelsQueryKey),\\n    [\\n      enabledModelsQueryIsFresh,\\n      enabledModelsIncludeProvider,\\n      queryClient,\\n      enabledModelsQueryKey,\\n    ],\\n  );\\n\\n  const overlayToggles = useRef<ToggleMap>(new Map());\\n  const unsentToggles = useRef<ToggleMap>(new Map());\\n  const fallbackModelData = useRef<EnabledModelsResponse | undefined>(\\n    undefined,\\n  );\\n  const activeToggleContext = useRef<ActiveToggleContext | undefined>(\\n    undefined,\\n  );\\n\\n  // After a mutation settles, remove its entries from the overlay \u2014 but\\n  // only when the current overlay value still matches what we sent. A\\n  // mismatch means the user re-toggled the same model mid-flight; that\\n  // entry already sits in ``unsentToggles`` for the next flush and must\\n  // not be dropped from the overlay until its own mutation settles.\\n  const clearSentOverlay = useCallback((sent: ToggleMap) => {\\n    for (const [key, sentUpdate] of sent) {\\n      if (overlayToggles.current.get(key)?.enabled === sentUpdate.enabled) {\\n        overlayToggles.current.delete(key);\\n      }\\n    }\\n    if (overlayToggles.current.size === 0) {\\n      fallbackModelData.current = undefined;\\n      activeToggleContext.current = undefined;\\n    }\\n  }, []);\\n\\n  const discardPendingToggleContext = useCallback(() => {\\n    const hadUnsentToggles = unsentToggles.current.size > 0;\\n    const discardedContext = activeToggleContext.current;\\n    const previousData = fallbackModelData.current;\\n    unsentToggles.current = new Map();\\n    overlayToggles.current = new Map();\\n    fallbackModelData.current = undefined;\\n    activeToggleContext.current = undefined;\\n\\n    if (discardedContext) {\\n      if (previousData) {\\n        queryClient.setQueryData(discardedContext.queryKey, previousData);\\n      }\\n      // setQueryData marks a query successful and clears invalidation. Restore\\n      // the rollback snapshot for display only, then immediately mark that\\n      // exact policy cache untrusted so stale grants cannot become actionable.\\n      void queryClient.invalidateQueries({\\n        queryKey: discardedContext.queryKey,\\n        exact: true,\\n      });\\n    }\\n    if (hadUnsentToggles) {\\n      setErrorData({\\n        title: t(\\\"errors.updateModelStatus\\\"),\\n        list: [t(\\\"modelProviders.errorUnexpected\\\")],\\n      });\\n    }\\n  }, [queryClient, setErrorData, t]);\\n\\n  // Shared flush prelude: builds the mutation payload, snapshots the\\n  // pre-toggle cache for rollback, and drains ``unsentToggles`` so a\\n  // follow-up flush triggered by a new user toggle cannot resend what we\\n  // just sent. Returns null when there's nothing to do so callers can\\n  // bail symmetrically.\\n  const buildAndConsumeToggleBatch = useCallback((): ToggleBatch | null => {\\n    if (!providerName || unsentToggles.current.size === 0) return null;\\n    const activeContext = activeToggleContext.current;\\n    if (!activeContext || activeContext.identity !== currentContextIdentity) {\\n      discardPendingToggleContext();\\n      return null;\\n    }\\n    if (!canMutateEnabledModels()) {\\n      discardPendingToggleContext();\\n      return null;\\n    }\\n\\n    const togglesToSend = new Map(unsentToggles.current);\\n\\n    const updates = Array.from(togglesToSend.values());\\n\\n    const previousData = fallbackModelData.current;\\n    unsentToggles.current = new Map();\\n\\n    return {\\n      updates,\\n      previousData,\\n      togglesToSend,\\n      queryKey: activeContext.queryKey,\\n      flowId: activeContext.flowId,\\n      projectId: activeContext.projectId,\\n    };\\n  }, [\\n    providerName,\\n    currentContextIdentity,\\n    canMutateEnabledModels,\\n    discardPendingToggleContext,\\n  ]);\\n\\n  // Shared error-path: drain the overlay BEFORE restoring previousData so\\n  // the re-overlay effect (triggered by setQueryData below) can't re-apply\\n  // a stale overlay over the rollback we just performed.\\n  const rollbackToggleBatch = useCallback(\\n    (\\n      togglesToSend: ToggleMap,\\n      previousData: EnabledModelsResponse | undefined,\\n      queryKey: ReturnType<typeof getEnabledModelsQueryKey>,\\n      error: unknown,\\n    ) => {\\n      clearSentOverlay(togglesToSend);\\n      if (previousData) {\\n        queryClient.setQueryData(queryKey, previousData);\\n      }\\n      setErrorData({\\n        title: t(\\\"errors.updateModelStatus\\\"),\\n        list: [getErrorMessage(error) || \\\"Failed to update model status\\\"],\\n      });\\n    },\\n    [clearSentOverlay, queryClient, setErrorData, t],\\n  );\\n\\n  const flushModelToggles = useDebounce(() => {\\n    const batch = buildAndConsumeToggleBatch();\\n    if (!batch) return;\\n    const {\\n      updates,\\n      previousData,\\n      togglesToSend,\\n      queryKey,\\n      flowId: batchFlowId,\\n      projectId: batchProjectId,\\n    } = batch;\\n\\n    updateEnabledModels(\\n      { updates, flowId: batchFlowId, projectId: batchProjectId },\\n      {\\n        onError: (error: unknown) => {\\n          rollbackToggleBatch(togglesToSend, previousData, queryKey, error);\\n        },\\n        onSettled: () => {\\n          clearSentOverlay(togglesToSend);\\n          queryClient.invalidateQueries({\\n            queryKey: [\\\"useGetEnabledModels\\\"],\\n          });\\n          queryClient.invalidateQueries({\\n            queryKey: [\\\"useGetModelProviders\\\"],\\n          });\\n          refreshAllModelInputs({ silent: true });\\n        },\\n      },\\n    );\\n  }, 1000);\\n\\n  useEffect(() => {\\n    const activeContext = activeToggleContext.current;\\n    if (activeContext && activeContext.identity !== currentContextIdentity) {\\n      flushModelToggles.cancel();\\n      discardPendingToggleContext();\\n    }\\n  }, [currentContextIdentity, discardPendingToggleContext, flushModelToggles]);\\n\\n  const flushOnUnmountRef = useRef(flushModelToggles);\\n  const discardOnUnmountRef = useRef(discardPendingToggleContext);\\n  flushOnUnmountRef.current = flushModelToggles;\\n  discardOnUnmountRef.current = discardPendingToggleContext;\\n  useEffect(\\n    () => () => {\\n      // Scope-keyed modal navigation unmounts this hook instead of rerendering\\n      // it with the next identity. Cancel the surviving lodash timer and roll\\n      // back only unsent intent; an explicit close already consumes its batch\\n      // through flushPendingChanges before unmount.\\n      flushOnUnmountRef.current.cancel();\\n      discardOnUnmountRef.current();\\n    },\\n    [],\\n  );\\n\\n  const flushPendingChanges = useCallback(async () => {\\n    // Cancel the pending debounce timer \u2014 we'll send the toggles directly\\n    flushModelToggles.cancel();\\n\\n    const batch = buildAndConsumeToggleBatch();\\n    if (!batch) return;\\n    const {\\n      updates,\\n      previousData,\\n      togglesToSend,\\n      queryKey,\\n      flowId: batchFlowId,\\n      projectId: batchProjectId,\\n    } = batch;\\n\\n    try {\\n      await updateEnabledModelsAsync({\\n        updates,\\n        flowId: batchFlowId,\\n        projectId: batchProjectId,\\n      });\\n      clearSentOverlay(togglesToSend);\\n      // Invalidate the affected queries inline so callers don't need to\\n      // bolt this on. The modal's onClose still triggers\\n      // ``refreshAllModelInputs`` afterwards to repopulate per-node\\n      // template options, but ``useGetEnabledModels`` consumers no longer\\n      // depend on the caller for cache freshness.\\n      queryClient.invalidateQueries({ queryKey: [\\\"useGetEnabledModels\\\"] });\\n      queryClient.invalidateQueries({ queryKey: [\\\"useGetModelProviders\\\"] });\\n    } catch (error: unknown) {\\n      rollbackToggleBatch(togglesToSend, previousData, queryKey, error);\\n    }\\n  }, [\\n    flushModelToggles,\\n    buildAndConsumeToggleBatch,\\n    updateEnabledModelsAsync,\\n    clearSentOverlay,\\n    rollbackToggleBatch,\\n    queryClient,\\n  ]);\\n\\n  const handleModelToggle = useCallback(\\n    (modelName: string, enabled: boolean, modelType: ModelType) => {\\n      if (!providerName || !canMutateEnabledModels()) return;\\n      const activeContext = activeToggleContext.current;\\n      if (activeContext && activeContext.identity !== currentContextIdentity) {\\n        flushModelToggles.cancel();\\n        discardPendingToggleContext();\\n        return;\\n      }\\n\\n      const update: ModelStatusUpdate = {\\n        provider: providerName,\\n        model_id: modelName,\\n        model_type: modelType,\\n        enabled,\\n      };\\n      const toggleIdentity = getToggleIdentity(\\n        currentContextIdentity,\\n        providerName,\\n        modelName,\\n        modelType,\\n      );\\n\\n      // Cancel any in-flight refetch of useGetEnabledModels so its (stale)\\n      // result cannot overwrite the optimistic cache update below. The\\n      // re-overlay effect handles refetches that start AFTER this point;\\n      // ``cancelQueries`` covers the ones already in flight at click time.\\n      void queryClient.cancelQueries({ queryKey: enabledModelsQueryKey });\\n\\n      if (overlayToggles.current.size === 0) {\\n        fallbackModelData.current =\\n          queryClient.getQueryData<EnabledModelsResponse>(\\n            enabledModelsQueryKey,\\n          );\\n        activeToggleContext.current = {\\n          identity: currentContextIdentity,\\n          queryKey: enabledModelsQueryKey,\\n          flowId,\\n          projectId,\\n        };\\n      }\\n\\n      queryClient.setQueryData<EnabledModelsResponse>(\\n        enabledModelsQueryKey,\\n        (old) => {\\n          if (!old) return old;\\n          return applyToggleToEnabledModels(old, update);\\n        },\\n      );\\n\\n      // Track in BOTH buffers: overlay for UI protection across refetches,\\n      // unsent for the next flush's payload.\\n      overlayToggles.current.set(toggleIdentity, update);\\n      unsentToggles.current.set(toggleIdentity, update);\\n      flushModelToggles();\\n    },\\n    [\\n      providerName,\\n      currentContextIdentity,\\n      canMutateEnabledModels,\\n      queryClient,\\n      flushModelToggles,\\n      enabledModelsQueryKey,\\n      discardPendingToggleContext,\\n      flowId,\\n      projectId,\\n    ],\\n  );\\n\\n  // Re-overlay effect \u2014 protects the pending-toggle window in its entirety,\\n  // not just the instant of the click. Any refetch (window focus, remount,\\n  // reconnect, or a stale-time expiry) that lands while ``overlayToggles``\\n  // has entries will surface the server's pre-toggle state into\\n  // ``enabledModelsData``; this effect detects the drift and re-applies the\\n  // pending overlay so the Switch tracks the user's intent through the\\n  // entire debounce + in-flight window. Once ``clearSentOverlay`` drains\\n  // the entry on settle, the next data emission is a no-op.\\n  useEffect(() => {\\n    if (!providerName) return;\\n    if (!enabledModelsData) return;\\n    const overlay = overlayToggles.current;\\n    if (overlay.size === 0) return;\\n\\n    const includesRevokedProvider = Array.from(overlay.values()).some(\\n      (update) =>\\n        !Object.hasOwn(enabledModelsData.enabled_models, update.provider),\\n    );\\n    if (includesRevokedProvider) {\\n      flushModelToggles.cancel();\\n      discardPendingToggleContext();\\n      return;\\n    }\\n\\n    // Loop guard: the ``setQueryData`` below re-emits ``enabledModelsData``\\n    // and re-runs this effect; ``drifted`` must return false on the second\\n    // pass for the recursion to terminate. Don't replace this with an\\n    // unconditional re-apply \u2014 the second invocation finds the overlay\\n    // already applied, ``getToggleEnabled`` matches every queued update, and\\n    // bails. Any future refactor that removes the drift check must\\n    // introduce an equivalent termination condition.\\n    const drifted = Array.from(overlay.values()).some(\\n      (update) =>\\n        getToggleEnabled(enabledModelsData, update) !== update.enabled,\\n    );\\n    if (!drifted) return;\\n\\n    queryClient.setQueryData<EnabledModelsResponse>(\\n      enabledModelsQueryKey,\\n      (old) => {\\n        if (!old) return old;\\n        return applyToggleMap(old, overlay);\\n      },\\n    );\\n  }, [\\n    enabledModelsData,\\n    providerName,\\n    queryClient,\\n    enabledModelsQueryKey,\\n    flushModelToggles,\\n    discardPendingToggleContext,\\n  ]);\\n\\n  return {\\n    handleModelToggle,\\n    flushPendingChanges,\\n  };\\n};\\n\"}]}";
